 * payload is the data origin; the collector itself is only the transport.
 *
 * Payment notifications parsed by the Android collector; the collector extracts structured
 * fields locally and the raw notification never leaves the device.
 */
@Serializable
enum class SourceKind(val value: String) {
    @SerialName("android.accessibility") ANDROID_ACCESSIBILITY("android.accessibility"),
    @SerialName("android.healthconnect") ANDROID_HEALTHCONNECT("android.healthconnect"),
    @SerialName("android.usagestats") ANDROID_USAGESTATS("android.usagestats"),
    @SerialName("android.wechatpay") ANDROID_WECHATPAY("android.wechatpay"),
    @SerialName("windows.foreground") WINDOWS_FOREGROUND("windows.foreground");
}

@Serializable
data class EventAcknowledgement(
    val error: Error? = null,

    @SerialName("event_id")
    val eventId: String,

    val revision: Long,
    val status: Status
)

@Serializable
enum class Status(val value: String) {
    @SerialName("accepted") ACCEPTED("accepted"),
    @SerialName("duplicate") DUPLICATE("duplicate"),
    @SerialName("rejected") REJECTED("rejected"),
    @SerialName("stale_revision") STALE_REVISION("stale_revision");
}

@Serializable
data class EventBatchRequest(
    val events: List<VersionedEvent>
)

@Serializable
data class EventBatchResponse(
    /**
     * Exactly one result for each submitted event, in the same order as the request array.
     */
    val results: List<EventAcknowledgement>
)

@Serializable
data class EventCorrectionRequest(
    /**
     * Structured field corrections to apply. Omitted or empty is allowed only when the request
     * changes the invalidation state.
     */
    val fields: List<CorrectionField>? = null,

    /**
     * Marks the observation invalid (a false positive) so it leaves default timeline views and
     * statistics while staying retained and auditable. Omitted keeps the current validity; a
     * request that neither changes fields nor the invalidation state is rejected.
     */
    val invalidate: Boolean? = null,

    /**
     * Optional Owner-provided reason recorded in the audit trail; never device raw text.
     */
    val reason: String? = null
)

@Serializable
data class EventCorrectionResult(
    /**
     * Dotted paths of the fields this correction changed.
     */
    @SerialName("changed_fields")
    val changedFields: List<String>,

    /**
     * UTC instant at which the correction was applied.
     */
    @SerialName("corrected_at")
    val correctedAt: String,

    val event: VersionedEvent,

    /**
     * Per affected metric, the report-day ranges and result count that rebuild.
     */
    val impact: List<CorrectionImpact>,

    /**
     * Validity of the latest revision after this correction.
     */
    val invalidated: Boolean,

    /**
     * The recorded reason, or null when the correction carried none.
     */
    val reason: String? = null,

    /**
     * Revision allocated by this correction in the reserved manual-correction space.
     */
    val revision: Long
)

@Serializable
data class EventPage(
    val context: QueryContext,
    val data: List<VersionedEvent>,
    val page: PageMetadata
)

@Serializable
data class QueryContext(
    val completeness: Completeness,

    /**
     * Presence semantics for the queried range, so a report never reads as a bare number:
     * observed means in-range observations produced the reported values; zero means
     * observations exist but the normalized value is explicitly 0; no_data means the range
     * holds no observations at all. Partial coverage is reported by completeness and competing
     * sources by source_conflicts.
     */
    @SerialName("data_state")
    val dataState: DataState? = null,

    val from: String,

    /**
     * Number of in-range observations flagged pending confirmation and awaiting Owner review.
     * Present on payment-domain reads; the transaction totals cover every observation including
     * these.
     */
    @SerialName("pending_confirmation_count")
    val pendingConfirmationCount: Long? = null,

    val provenance: List<String>,

    /**
     * Competing observations the source policy resolved (or, for payment candidates, deferred
     * to the Owner). Competing observations stay retained and are referenced by their event
     * identifiers.
     */
    @SerialName("source_conflicts")
    val sourceConflicts: List<SourceConflict>? = null,

    /**
     * Version of the source policy that produced this response's normalized results. Present on
     * single-domain reads (metrics, health, payment); absent for cross-domain event reads where
     * one version cannot describe every domain.
     */
    @SerialName("source_policy_version")
    val sourcePolicyVersion: Long? = null,

    val timezone: String,
    val to: String
)

@Serializable
enum class Completeness(val value: String) {
    @SerialName("complete") COMPLETE("complete"),
    @SerialName("partial") PARTIAL("partial"),
    @SerialName("unknown") UNKNOWN("unknown");
}

/**
 * Presence semantics for the queried range, so a report never reads as a bare number:
 * observed means in-range observations produced the reported values; zero means
 * observations exist but the normalized value is explicitly 0; no_data means the range
 * holds no observations at all. Partial coverage is reported by completeness and competing
 * sources by source_conflicts.
 */
@Serializable
enum class DataState(val value: String) {
    @SerialName("no_data") NO_DATA("no_data"),
    @SerialName("observed") OBSERVED("observed"),
    @SerialName("zero") ZERO("zero");
}

@Serializable
data class SourceConflict(
    /**
     * Stable identifiers of the competing observations. They stay retained and individually
     * readable; the policy withholds them from the normalized result without deleting anything.
     */
    @SerialName("competing_event_ids")
    val competingEventIds: List<String>,

    /**
     * Sources with retained observations the policy did not select.
     */
    @SerialName("competing_sources")
    val competingSources: List<String>,

    /**
     * Start of the conflict window (UTC).
     */
    val from: String,

    /**
     * Metric key the conflict belongs to, such as usage.app_minutes, health.sleep_minutes, or
     * payment.transaction_totals.
     */
    val metric: String,

    /**
     * Source policy version that made the selection.
     */
    @SerialName("policy_version")
    val policyVersion: Long,

    /**
     * Stable identifiers of the selected observations inside the conflict window. Normalized
     * results reference these source event identifiers.
     */
    @SerialName("selected_event_ids")
    val selectedEventIds: List<String>,

    /**
     * Source the policy selected: a source kind for usage and payment metrics, a Health Connect
     * data origin for health metrics.
     */
    @SerialName("selected_source")
    val selectedSource: String,

    /**
     * End of the conflict window (UTC).
     */
    val to: String
)

@Serializable
data class PageMetadata(
    /**
     * Opaque cursor, or null when no further page exists.
     */
    @SerialName("next_cursor")
    val nextCursor: String? = null,

    @SerialName("page_size")
    val pageSize: Long
)

@Serializable
data class HeartbeatRequest(
    val activity: HeartbeatActivity,

    /**
     * UTC instant at which the device observed the reported current state. Heartbeat ordering,
     * freshness, and expiry are decided from this instant, so a heartbeat queued during an
     * outage can never pretend to be fresher than the moment it describes.
     */
    @SerialName("captured_at")
    val capturedAt: String,

    /**
     * Optional human-readable display label of the device. It is display metadata only; the
     * server-bound device identity always comes from the authenticated Device Token.
     */
    @SerialName("device_name")
    val deviceName: String? = null,

    /**
     * Collector platform the heartbeat originates from.
     */
    val platform: Platform
)

@Serializable
data class OwnerPasswordRequest(
    /**
     * The Owner password. Never logged or stored in plaintext.
     */
    val password: String
)

@Serializable
data class OwnerSessionInfo(
    /**
     * Always true when the endpoint responds 200.
     */
    val authenticated: Boolean
)

@Serializable
data class OwnerSettings(
    /**
     * IANA timezone defining the default day and week boundaries for reports. Defaults to UTC
     * until the Owner configures another timezone; browser timezones never change a report.
     */
    @SerialName("report_timezone")
    val reportTimezone: String
)

@Serializable
data class OwnerSettingsUpdate(
    /**
     * New report timezone as an IANA timezone name.
     */
    @SerialName("report_timezone")
    val reportTimezone: String
)

@Serializable
data class OwnerStatus(
    /**
     * True once the single implicit Owner password has been created.
     */
    val initialized: Boolean
)

@Serializable
data class SourcePolicyDocument(
    val entries: List<SourcePolicyEntry>,

    /**
     * Set on update responses: for each changed metric, the report-day ranges and normalized
     * result count the change affected. The same statement is appended to the audit log.
     */
    val impact: List<SourcePolicyImpact>? = null,

    /**
     * When this version was written; null for the untouched default.
     */
    @SerialName("updated_at")
    val updatedAt: String? = null,

    /**
     * Monotonic policy version. Version 1 with the documented default priorities applies until
     * the Owner changes the policy.
     */
    val version: Long
)

@Serializable
data class SourcePolicyEntry(
    /**
     * Metric key with an explicit priority. Usage and payment metrics prioritize source kinds;
     * health metrics prioritize Health Connect data origins.
     */
    val metric: String,

    /**
     * Source kinds or data origins from highest to lowest priority. The highest-priority source
     * with observations in a conflict window wins; an empty list means no explicit preference,
     * with all sources ranking deterministically by name. Competing observations are never
     * deleted.
     */
    val priority: List<String>
)

@Serializable
data class SourcePolicyImpact(
    /**
     * Report-day ranges whose normalized selection differs between the old and new policy.
     * Empty when no stored observation competes differently.
     */
    @SerialName("affected_ranges")
    val affectedRanges: List<SourcePolicyImpactAffectedRange>,

    @SerialName("from_version")
    val fromVersion: Long,

    /**
     * Metric key whose priority changed.
     */
    val metric: String,

    /**
     * Number of normalized day results the change affected.
     */
    @SerialName("result_count")
    val resultCount: Long,

    /**
     * IANA report timezone the affected ranges resolve in, so the audit statement is
     * reproducible.
     */
    val timezone: String,

    @SerialName("to_version")
    val toVersion: Long
)

@Serializable
data class SourcePolicyImpactAffectedRange(
    val from: String,
    val to: String
)

@Serializable
data class SourcePolicyUpdateRequest(
    /**
     * Full replacement of the policy entries. Omitted metrics keep the default priority; a
     * policy change only rebuilds derived results and never modifies raw observations.
     */
    val entries: List<SourcePolicyEntry>
)

@Serializable
data class UsageDayMetrics(
    @SerialName("active_minutes")
    val activeMinutes: Long,

    /**
     * Local calendar day in the report timezone.
     */
    val date: String,

    @SerialName("device_minutes")
    val deviceMinutes: Long
)

@Serializable
data class UsageDayReport(
    val context: QueryContext,

    /**
     * The requested local calendar day.
     */
    val date: String,

    /**
     * One entry per device lane contributing intervals to the day.
     */
    val devices: List<UsageDeviceMetrics>,

    val metrics: UsageMetrics,

    /**
     * IANA timezone the day boundaries resolved in.
     */
    val timezone: String
)

@Serializable
data class UsageDeviceMetrics(
    /**
     * Deduplicated non-AFK time of this device lane; lane unions do not de-duplicate across
     * devices.
     */
    @SerialName("active_minutes")
    val activeMinutes: Long,

    /**
     * Device lane identifier as reported in the event envelope.
     */
    @SerialName("device_id")
    val deviceId: String,

    /**
     * Device minutes attributed to this device lane.
     */
    @SerialName("device_minutes")
    val deviceMinutes: Long,

    val platform: Platform
)

@Serializable
data class UsageMetrics(
    /**
     * Active minutes: the union of qualifying non-AFK intervals over the report range.
     * Overlapping or adjacent device time counts once.
     */
    @SerialName("active_minutes")
    val activeMinutes: Long,

    /**
     * Device minutes: the sum of qualifying device intervals overlapping the report range
     * across all devices, including AFK foreground time. Concurrent device use can exceed
     * elapsed wall-clock time.
     */
    @SerialName("device_minutes")
    val deviceMinutes: Long
)

@Serializable
data class UsageWeekReport(
    val context: QueryContext,

    /**
     * One entry per local day of the week, in order.
     */
    val days: List<UsageDayMetrics>,

    val metrics: UsageMetrics,

    /**
     * IANA timezone the week boundaries resolved in.
     */
    val timezone: String,

    /**
     * Last local day of the Monday-start week in the report timezone.
     */
    @SerialName("week_end_date")
    val weekEndDate: String,

    /**
     * First local day of the Monday-start week in the report timezone.
     */
    @SerialName("week_start_date")
    val weekStartDate: String
)
